Object.assign(SNIP,{"h5thoat": "bool coCap(const vector<int>& a, int s) {\n    for (int i = 0; i < (int)a.size(); i++)\n        for (int j = i + 1; j < (int)a.size(); j++)\n            if (a[i] + a[j] == s) return true;   // thoát cả hai vòng\n    return false;\n}", "h5mau": "#include <bits/stdc++.h>\nusing namespace std;\n\n// tính chất X: tổng các chữ số chia hết cho 3\nint tongChuSo(long long x) {\n    int s = 0;\n    while (x > 0) {\n        s += x % 10;\n        x /= 10;\n    }\n    return s;\n}\n\nbool laX(long long x) {\n    return tongChuSo(x) % 3 == 0;\n}\n\nint main() {\n    long long a = 10, b = 30;\n    int dem = 0;\n    for (long long x = a; x <= b; x++)\n        if (laX(x)) dem++;\n    cout << dem << \"\\n\";\n    return 0;\n}"});PRESET_NOTES["l5"]={"Ví dụ: Đếm số có tổng chữ số chia hết cho 3": "Viết thẳng trong main cũng chạy, nhưng khó đọc và khó thử từng phần. So sánh với đoạn code chia hàm ở mục trên.", "Ví dụ: Hàm trả về hai giá trị qua tham chiếu": "mn và mx là tham chiếu tới lo và hi của main: gán mn là gán lo. Vector a truyền bằng const& nên không bị chép.", "Lỗi: Mảng quá lớn trong main": "Mảng 3·10⁶ số int chiếm 12 MB trên stack, vượt giới hạn 8 MB: chương trình dừng với lỗi tràn stack (trên máy thật thường là Segmentation fault). Chuyển dòng khai báo ra ngoài main là hết lỗi.", "Ví dụ: Mảng lớn khai báo toàn cục": "Biến toàn cục không nằm trên stack nên mảng lớn vẫn được, và mọi phần tử bắt đầu bằng 0."};EX_HINTS["l5"]=[["Hàm dao(x) đảo ngược các chữ số: r = r * 10 + x % 10.", "x đối xứng khi dao(x) == x."], ["Ước đi theo cặp i và n / i, nên chỉ cần duyệt i với i · i ≤ n (khoảng 31 623 lần với n = 10⁹).", "Đừng cộng hai lần khi i = n / i.", "n = 1 không có ước nào nhỏ hơn nó: không hoàn hảo."]];
