const PR5=[{label:"Ví dụ: Đếm số có tổng chữ số chia hết cho 3",input:"10 30",code:"#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    if (fopen(\"DEMX.INP\", \"r\")) {\n        freopen(\"DEMX.INP\", \"r\", stdin);\n        freopen(\"DEMX.OUT\", \"w\", stdout);\n    }\n    long long a, b;\n    cin >> a >> b;\n    int dem = 0;\n    for (long long x = a; x <= b; x++) {\n        long long t = x;\n        int s = 0;\n        while (t > 0) {\n            s += t % 10;\n            t /= 10;\n        }\n        if (s % 3 == 0) dem++;\n    }\n    cout << dem << \"\\n\";\n    return 0;\n}",viz:[{type:"vars",names:["x","t","s","dem"]}]},{label:"Ví dụ: Hàm trả về hai giá trị qua tham chiếu",input:"",code:"#include <bits/stdc++.h>\nusing namespace std;\n\nvoid minMax(const vector<int>& a, int& mn, int& mx) {\n    mn = a[0];\n    mx = a[0];\n    for (int x : a) {\n        mn = min(mn, x);\n        mx = max(mx, x);\n    }\n}\n\nint main() {\n    vector<int> a = {5, -2, 9, 0, 7};\n    int lo, hi;\n    minMax(a, lo, hi);\n    cout << lo << \" \" << hi << \"\\n\";\n    return 0;\n}"},{label:"Lỗi: Mảng quá lớn trong main",input:"",code:"#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    int a[3000000];\n    a[0] = 1;\n    cout << a[0] << \"\\n\";\n    return 0;\n}"},{label:"Ví dụ: Mảng lớn khai báo toàn cục",input:"",code:"#include <bits/stdc++.h>\nusing namespace std;\n\nint a[3000000];\n\nint main() {\n    a[0] = 1;\n    cout << a[0] << \" \" << a[2999999] << \"\\n\";\n    return 0;\n}"}];
